{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Investment</title>
  <style>
    :root{--bg:#fff8f2;--accent:#ff6b6b;--muted:#6b6b6b;--card:#ffffff;--glass:rgba(255,255,255,0.6);--shadow:0 8px 30px rgba(11,12,14,0.06)}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial}
    body{background:linear-gradient(180deg, #fff 20%, var(--bg) 100%);color:#111}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(90deg, rgba(255,255,255,0.6), rgba(255,255,255,0.4));backdrop-filter:blur(6px);position:sticky;top:0;z-index:40;border-bottom:1px solid rgba(0,0,0,0.03)}
    .logo{display:flex;align-items:center;gap:10px;font-weight:700;color:var(--accent)}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:1100px;margin:28px auto;padding:0 22px}
    .hero{display:grid;grid-template-columns:1fr 340px;gap:24px;align-items:start}
    .hero .lead{background:var(--card);padding:28px;border-radius:14px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px;font-size:28px;color:#15233a}
    p.lead-copy{margin:0;color:var(--muted);line-height:1.5}
    .cta-row{margin-top:18px;display:flex;gap:12px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;font-weight:700;cursor:pointer}
    .ghost{background:transparent;border:1px solid rgba(21,35,58,0.08);padding:9px 12px;border-radius:10px}

    /* Pricing comparator */
    .side{background:linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.6));padding:22px;border-radius:12px;box-shadow:var(--shadow)}
    .toggle{display:flex;align-items:center;justify-content:center;gap:12px;margin-bottom:16px}
    .toggle .switch{width:74px;height:36px;border-radius:999px;background:linear-gradient(90deg,#f2f4f6,#ffffff);display:flex;align-items:center;padding:4px;cursor:pointer;border:1px solid rgba(0,0,0,0.04)}
    .knob{width:28px;height:28px;border-radius:999px;background:var(--accent);box-shadow:0 6px 14px rgba(255,107,107,0.18);transition:transform .36s cubic-bezier(.2,.9,.3,1)}
    .knob.right{transform:translateX(36px)}
    .plans{display:grid;grid-template-columns:1fr;gap:12px}
    .plan{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff,#fffdf9);border:1px solid rgba(17,19,21,0.04)}
    .plan .meta{display:flex;flex-direction:column}
    .plan .name{font-weight:700}
    .price{font-weight:900;color:#13212d;font-size:20px}
    .sub{color:var(--muted);font-size:13px}
    .savings{font-size:12px;color:green;font-weight:700}

    /* Grid for full pricing details */
    .grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin-top:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow);border:1px solid rgba(0,0,0,0.03)}
    ul{padding-left:18px;margin:12px 0 0;color:var(--muted)}
    footer{margin:36px 0 80px;text-align:center;color:var(--muted)}

    /* responsive */
    @media (max-width:900px){.hero{grid-template-columns:1fr;}.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class='logo'>{{BUSINESS_NAME}}</div>
    <nav>
      <a href='index.html'>Start</a>
      <a href='about.html'>Story</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Series</a>
      <a href='pricing.html'>Investment</a>
      <a href='testimonials.html'>Voices</a>
      <a href='book.html'>Book</a>
      <a href='contact.html'>Reach</a>
    </nav>
  </header>

  <main class='wrap'>
    <section class='hero'>
      <div class='lead'>
        <h1>Investment designed for real schedules</h1>
        <p class='lead-copy'>Choose a rhythm that fits your weeks. Monthly access is great for ongoing adjustments; packaged intensives are for a focused reset. Values below animate so you can compare at a glance.</p>
        <div class='cta-row'>
          <button class='btn' onclick='location.href="{{PRIMARY_CTA_URL}}"'>{{PRIMARY_CTA_LABEL}}</button>
          <button class='ghost' onclick='location.href="contact.html"'>Ask a question</button>
        </div>
      </div>

      <aside class='side'>
        <div class='toggle' aria-hidden='false'>
          <div style='font-size:13px;color:var(--muted)'>Monthly</div>
          <div class='switch' id='billingToggle' role='button' aria-pressed='false'>
            <div class='knob' id='knob'></div>
          </div>
          <div style='font-size:13px;color:var(--muted)'>Package</div>
        </div>

        <div class='plans' id='plans'>
          <div class='plan' data-month='49' data-package='240'>
            <div class='meta'><div class='name'>Pulse Plan</div><div class='sub'>Light weekly check-ins</div></div>
            <div>
              <div class='price' data-display>—</div>
              <div class='sub' data-sub>per month</div>
            </div>
          </div>

          <div class='plan' data-month='99' data-package='540'>
            <div class='meta'><div class='name'>Rhythm Plan</div><div class='sub'>Priority scheduling + toolkit</div></div>
            <div>
              <div class='price' data-display>—</div>
              <div class='sub' data-sub>per month</div>
            </div>
          </div>

          <div class='plan' data-month='199' data-package='960'>
            <div class='meta'><div class='name'>Anchor Plan</div><div class='sub'>Deep dive series + follow-up</div></div>
            <div>
              <div class='price' data-display>—</div>
              <div class='sub' data-sub>per month</div>
            </div>
          </div>
        </div>

        <div style='margin-top:12px;font-size:13px;color:var(--muted)'>Switch to compare one-time package pricing and see the effective saving.</div>
      </aside>
    </section>

    <section class='grid' aria-label='Full pricing'>
      <div class='card'>
        <h3 style='margin:0 0 6px'>What you get</h3>
        <ul>
          <li>Short, practical frameworks you can test during busy weeks</li>
          <li>Clear, repeatable habits and a weekly check-in</li>
          <li>Templates for planning and evening reset</li>
        </ul>
      </div>

      <div class='card'>
        <h3 style='margin:0 0 6px'>How billing works</h3>
        <p style='margin:0;color:var(--muted)'>Monthly plans renew automatically. Packages are billed once and include a recommended action plan for the following 8 weeks.</p>
      </div>

      <div class='card'>
        <h3 style='margin:0 0 6px'>Custom teams & groups</h3>
        <p style='margin:0;color:var(--muted)'>Events and cohorts are quoted separately. Reach out for a tailored proposal.</p>
      </div>
    </section>

    <footer>
      <div>Prefer a tailored quote? Call <a href='tel:{{PHONE}}'>{{PHONE}}</a> or email <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
    </footer>
  </main>

  <script>
    // Pricing comparator with animated numbers
    (function(){
      const toggle = document.getElementById('billingToggle');
      const knob = document.getElementById('knob');
      const plans = Array.from(document.querySelectorAll('.plan'));
      let mode = 'monthly';

      function formatCurrency(n){
        return '$' + n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
      }

      function animateNumber(el, from, to, duration=600){
        const start = performance.now();
        function frame(now){
          const progress = Math.min((now - start)/duration, 1);
          const value = Math.round(from + (to - from) * ease(progress));
          el.textContent = formatCurrency(value);
          if(progress < 1) requestAnimationFrame(frame);
        }
        function ease(t){ return 1 - Math.pow(1 - t, 3); }
        requestAnimationFrame(frame);
      }

      function updateDisplay(){
        plans.forEach(plan => {
          const monthly = Number(plan.getAttribute('data-month'));
          const pack = Number(plan.getAttribute('data-package'));
          const display = plan.querySelector('[data-display]');
          const sub = plan.querySelector('[data-sub]');
          if(mode === 'monthly'){
            animateNumber(display, Number(display.textContent.replace(/[^0-9]/g,'')) || monthly, monthly);
            sub.textContent = 'per month';
          } else {
            animateNumber(display, Number(display.textContent.replace(/[^0-9]/g,'')) || pack, pack);
            sub.textContent = 'one-time package';
          }
        });
      }

      // initial render
      plans.forEach(plan => {
        const display = plan.querySelector('[data-display]');
        display.textContent = '—';
      });
      setTimeout(updateDisplay,120);

      toggle.addEventListener('click', ()=>{
        mode = (mode === 'monthly') ? 'package' : 'monthly';
        toggle.setAttribute('aria-pressed', mode === 'package');
        if(mode === 'package') knob.classList.add('right'); else knob.classList.remove('right');
        updateDisplay();
      });

    })();
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Voices</title>
  <style>
    :root{--bg:#f7fff9;--accent:#2b8a78;--muted:#556;--card:#fff;--shadow:0 10px 30px rgba(11,12,14,0.06)}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:var(--bg);color:#102022}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;background:rgba(255,255,255,0.7);backdrop-filter:blur(6px);border-bottom:1px solid rgba(0,0,0,0.04)}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .wrap{max-width:980px;margin:28px auto;padding:0 20px}
    h1{margin:0 0 10px;font-size:26px}
    .lead{display:flex;gap:18px;align-items:flex-start}
    .mood{background:var(--card);padding:12px;border-radius:12px;box-shadow:var(--shadow);flex:0 0 220px}
    .content{flex:1}
    .mood button{display:block;width:100%;text-align:left;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.04);background:transparent;margin-bottom:8px;cursor:pointer}
    .mood button.active{background:linear-gradient(90deg,rgba(43,138,120,0.1),rgba(43,138,120,0.06));border-color:rgba(43,138,120,0.18)}
    .approach{background:var(--card);padding:16px;border-radius:12px;box-shadow:var(--shadow);margin-bottom:16px}
    .testi-wrap{display:grid;grid-template-columns:1fr 1fr;gap:12px}
    .testi{background:linear-gradient(180deg,#fff,#fbfffc);padding:14px;border-radius:10px;border:1px solid rgba(0,0,0,0.03)}
    .cta{display:flex;gap:10px;margin-top:12px}
    .btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:0;cursor:pointer}
    .sub{color:var(--muted);font-size:13px}
    @media(max-width:800px){.lead{flex-direction:column}.testi-wrap{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style='font-weight:700;color:var(--accent)'>{{BUSINESS_NAME}}</div>
    <nav>
      <a href='index.html'>Start</a>
      <a href='about.html'>Story</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Series</a>
      <a href='pricing.html'>Investment</a>
      <a href='testimonials.html'>Voices</a>
      <a href='book.html'>Book</a>
      <a href='contact.html'>Reach</a>
    </nav>
  </header>

  <main class='wrap'>
    <h1>Voices and quick patterns that stuck</h1>
    <p class='sub'>Read how small structural shifts helped people reclaim clearer blocks of time and steadier focus without adding complexity.</p>

    <div class='lead' style='margin-top:18px'>
      <aside class='mood' aria-label='Mood selector'>
        <div style='font-weight:700;margin-bottom:8px'>How are you feeling today?</div>
        <button data-mood='overwhelmed' class='active'>Overwhelmed — too many starts</button>
        <button data-mood='stuck'>Stuck — same cycles repeat</button>
        <button data-mood='steady'>Steady — want to deepen</button>
        <button data-mood='curious'>Curious — want a test run</button>

        <div style='margin-top:10px;color:var(--muted);font-size:13px'>Choose a state to filter perspectives and reveal the recommended approach below.</div>
      </aside>

      <section class='content'>
        <div class='approach' id='approach'>
          <div style='display:flex;justify-content:space-between;align-items:start'>
            <div>
              <div style='font-weight:800' id='approachTitle'>Restore simple boundaries</div>
              <div class='sub' id='approachBlurb'>A short reset practice to reclaim 90 minutes each week with tiny structural changes.</div>
            </div>
            <div style='text-align:right'>
              <div style='font-size:12px;color:var(--muted)'>Recommended</div>
              <div style='font-weight:900;color:var(--accent);margin-top:6px' id='approachTag'>4-week reset</div>
            </div>
          </div>

          <div class='cta' style='margin-top:12px'>
            <button class='btn' id='approachCta'>Book a 30-min clarity call</button>
            <button class='ghost' onclick='location.href="testimonials.html"' style='border:1px solid rgba(0,0,0,0.06);padding:10px;border-radius:8px;background:transparent'>Read all voices</button>
          </div>
        </div>

        <div class='testi-wrap' id='testimonials'>
          <div class='testi' data-for='overwhelmed'>
            "I moved from day-to-day firefighting to a predictable weekly rhythm. What I learned fit into my calendar without negotiation." — Mara, product manager
          </div>
          <div class='testi' data-for='stuck'>
            "The step-by-step approach helped me stop spending energy deciding and start acting. It feels sustainable." — Ben, consultant
          </div>
          <div class='testi' data-for='steady'>
            "Once I had a consistent check-in process, I could build on small wins and feel fewer urgent pivots." — Lila, creative director
          </div>
          <div class='testi' data-for='curious'>
            "A short trial clarified which tools mattered — and which I could drop. That made it easy to continue." — Omar, teacher
          </div>
        </div>
      </section>
    </div>

    <footer style='margin-top:30px;color:var(--muted)'>
      Prefer to talk first? Call <a href='tel:{{PHONE}}'>{{PHONE}}</a> or email <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a>.
    </footer>
  </main>

  <script>
    // Mood-to-Method selector: morphs recommended approach and CTA
    (function(){
      const buttons = Array.from(document.querySelectorAll('.mood button'));
      const approachTitle = document.getElementById('approachTitle');
      const approachBlurb = document.getElementById('approachBlurb');
      const approachTag = document.getElementById('approachTag');
      const approachCta = document.getElementById('approachCta');
      const testimonialEls = Array.from(document.querySelectorAll('.testi'));

      const map = {
        'overwhelmed':{
          title:'Create a clear boundary scaffold',
          blurb:'A three-step boundary practice to protect time and reduce reactive work in the week ahead.',
          tag:'Starter reset',
          cta:'Schedule a boundary clarity call'
        },
        'stuck':{
          title:'Interrupt the loop with fresh constraints',
          blurb:'Use purposeful limits to test new routines and see which small changes stick longer than a week.',
          tag:'Cycle breaker',
          cta:'Try the 2-week focused series'
        },
        'steady':{
          title:'Deepen a winning rhythm',
          blurb:'Extend practices with checkpoints and a simple review system to compound reliable progress.',
          tag:'Deepen program',
          cta:'Request program details'
        },
        'curious':{
          title:'A short experiment to test fit',
          blurb:'Keep it lightweight: try a single framework for two weeks and evaluate with a short reflection tool.',
          tag:'Trial plan',
          cta:'Start a 2-week experiment'
        }
      };

      function setMood(key){
        buttons.forEach(b=>b.classList.toggle('active', b.getAttribute('data-mood')===key));
        const m = map[key];
        approachTitle.textContent = m.title;
        approachBlurb.textContent = m.blurb;
        approachTag.textContent = m.tag;
        approachCta.textContent = m.cta;

        // Filter testimonials
        testimonialEls.forEach(el=>{
          if(el.getAttribute('data-for')===key){
            el.style.display = 'block';
            el.style.opacity = '1';
            el.style.transform = 'none';
          } else {
            el.style.display = 'none';
          }
        });
      }

      // initial
      setMood('overwhelmed');

      buttons.forEach(btn=>{
        btn.addEventListener('click', ()=>setMood(btn.getAttribute('data-mood')));
      });

      // CTA navigates to booking with query
      approachCta.addEventListener('click', ()=>{
        const q = encodeURIComponent(approachTag.textContent);
        location.href = 'book.html?from=' + q;
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Book</title>
  <style>
    :root{--bg:#f5f9ff;--accent:#3b82f6;--muted:#556;--card:#fff;--shadow:0 12px 40px rgba(11,12,14,0.06)}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:var(--bg);color:#0b1b2b}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;background:rgba(255,255,255,0.7);backdrop-filter:blur(6px);border-bottom:1px solid rgba(0,0,0,0.04)}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .wrap{max-width:880px;margin:36px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:20px}
    .form-card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    label{display:block;font-size:13px;margin-top:12px;color:var(--muted)}
    input[type='text'],input[type='email'],textarea,select{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);font-size:14px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;cursor:pointer;margin-top:12px}
    .method{background:linear-gradient(180deg,#fff,#f7fbff);padding:12px;border-radius:10px;border:1px solid rgba(0,0,0,0.03)}
    .modes{display:flex;gap:8px;margin-top:10px}
    .mode{padding:8px 10px;border-radius:999px;border:1px solid rgba(0,0,0,0.05);cursor:pointer;background:transparent}
    .mode.active{background:var(--accent);color:white}
    .hint{font-size:13px;color:var(--muted);margin-top:8px}
    @media(max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style='font-weight:700;color:var(--accent)'>{{BUSINESS_NAME}}</div>
    <nav>
      <a href='index.html'>Start</a>
      <a href='about.html'>Story</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Series</a>
      <a href='pricing.html'>Investment</a>
      <a href='testimonials.html'>Voices</a>
      <a href='book.html'>Book</a>
      <a href='contact.html'>Reach</a>
    </nav>
  </header>

  <main class='wrap'>
    <h1 style='margin:0 0 8px'>Book a session</h1>
    <p class='hint'>Choose the kind of session you want. The page will suggest the right format and update the booking CTA.</p>

    <div class='grid'>
      <div class='form-card'>
        <form id='bookingForm' action='https://example.com/submit' method='post'>
          <label for='name'>Your name</label>
          <input id='name' name='name' type='text' placeholder='Full name' required>

          <label for='email'>Email</label>
          <input id='email' name='email' type='email' placeholder='you@domain.com' required>

          <label for='phone'>Phone</label>
          <input id='phone' name='phone' type='text' placeholder='{{PHONE}}'>

          <label for='city'>City</label>
          <input id='city' name='city' type='text' placeholder='{{CITY}}'>

          <label for='state'>State</label>
          <input id='state' name='state' type='text' placeholder='{{STATE}}'>

          <label for='note'>Brief note (what's top of mind?)</label>
          <textarea id='note' name='note' rows='4' placeholder='A sentence or two'></textarea>

          <input type='hidden' id='selectedMethod' name='selectedMethod' value='Clarity Call'>

          <button class='btn' id='submitBtn' type='submit'>Book a 30-min clarity call</button>
        </form>
      </div>

      <aside class='method'>
        <div style='font-weight:800'>Mood-to-Method</div>
        <div style='color:var(--muted);font-size:13px;margin-top:6px'>Select how you feel and we’ll suggest a session format.</div>
        <div class='modes' role='tablist' aria-label='Method selector'>
          <button class='mode active' data-method='Clarity Call'>Overwhelmed</button>
          <button class='mode' data-method='Focus Session'>Stuck</button>
          <button class='mode' data-method='Deep Series'>Steady</button>
          <button class='mode' data-method='Trial Session'>Curious</button>
        </div>

        <div id='methodCard' style='margin-top:12px'>
          <div style='font-weight:700' id='methodTitle'>Clarity Call — 30 minutes</div>
          <div class='hint' id='methodDesc'>A short conversation to identify one structural change you can use this week.</div>
          <div style='margin-top:12px'>
            <div style='font-size:13px;color:var(--muted)'>Availability</div>
            <div style='margin-top:6px;color:#0b1b2b;font-weight:700' id='availability'>{{STATE}} schedule shown after booking</div>
          </div>
        </div>
      </aside>
    </div>

    <footer style='margin-top:28px;color:var(--muted)'>If you need invoicing or group sessions, email <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a>.</footer>
  </main>

  <script>
    // Mood-to-Method selector on booking page
    (function(){
      const modes = Array.from(document.querySelectorAll('.mode'));
      const methodTitle = document.getElementById('methodTitle');
      const methodDesc = document.getElementById('methodDesc');
      const selectedMethodInput = document.getElementById('selectedMethod');
      const submitBtn = document.getElementById('submitBtn');

      const map = {
        'Clarity Call':{
          title:'Clarity Call — 30 minutes',
          desc:'A focused check-in to identify one immediate structure to protect time this week.',
          cta:'Book a 30-min clarity call'
        },
        'Focus Session':{
          title:'Focus Session — 60 minutes',
          desc:'A tactical hour to redesign a single week and create a repeatable template.',
          cta:'Schedule a 60-min focus session'
        },
        'Deep Series':{
          title:'Deep Series — 4 sessions',
          desc:'A short series for habit formation, checkpoints, and tailored templates to sustain change.',
          cta:'Request series details'
        },
        'Trial Session':{
          title:'Trial Session — 45 minutes',
          desc:'A practical trial to test one framework with a follow-up note and recommended next steps.',
          cta:'Start a trial session'
        }
      };

      function setMethod(key){
        modes.forEach(m=>m.classList.toggle('active', m.getAttribute('data-method')===key));
        const info = map[key];
        methodTitle.textContent = info.title;
        methodDesc.textContent = info.desc;
        selectedMethodInput.value = info.title;
        submitBtn.textContent = info.cta;
      }

      modes.forEach(m=>m.addEventListener('click', ()=>setMethod(m.getAttribute('data-method'))));

      // If the page has a query from testimonials, set initial method
      (function checkQuery(){
        try{
          const params = new URLSearchParams(location.search);
          const from = params.get('from');
          if(from){
            // pick a method based on the tag
            if(/reset|Starter/i.test(from)) setMethod('Clarity Call');
            else if(/Cycle|breaker/i.test(from)) setMethod('Focus Session');
            else if(/Deepen/i.test(from)) setMethod('Deep Series');
            else if(/Trial/i.test(from)) setMethod('Trial Session');
          }
        }catch(e){}
      })();

      // Simple client-side validation to show chosen method in alert (since no backend)
      document.getElementById('bookingForm').addEventListener('submit', function(e){
